def min_cost_to_win(n, a):
    friend_index = a.index(-1)
    a[friend_index] = 0

    cost = 0
    for i in range(n.bit_length() - 1, 0, -1):
        current_layer = [j for j in range(n) if (j >> i) & 1]
        if friend_index in current_layer:
            friend_pos = current_layer.index(friend_index)
            if friend_pos % 2 == 1:
                cost += min(a[j] for j in current_layer if j < friend_index)
            else:
                cost += min(a[j] for j in current_layer if j > friend_index)
            friend_index //= 2
        else:
            friend_pos = next(j for j, pos in enumerate(current_layer) if pos > friend_index)
            if j % 2 == 1:
                cost += min(a[k] for k in current_layer if k < friend_index)
            else:
                cost += min(a[k] for k in current_layer if k > friend_index)
            friend_index = (friend_index + 1) // 2

    return cost

n = int(input())
