def min_dollars_to_win_tournament(n, a):
    friend_index = a.index(-1)
    a[friend_index] = 0

    def calculate_cost(start, end):
        if end - start <= 1:
            return 0

        mid = (start + end) // 2
        left_cost = calculate_cost(start, mid)
        right_cost = calculate_cost(mid, end)

        min_cost = float('inf')
        for i in range(start, mid):
            for j in range(mid, end):
                if a[i] > a[j]:
                    cost = left_cost + right_cost + a[i]
                else:
                    cost = left_cost + right_cost + a[j]
                min_cost = min(min_cost, cost)

        return min_cost

    return calculate_cost(0, n)

